// WORKER LIFECYCLE:

@Component
public class JobWorker {

    @Scheduled(fixedDelay = 1000) // poll every second
    public void processNextJob() {
        Optional<Job> job = jobQueue.fetchAndLock(workerId);
        if (job.isEmpty()) return;

        try {
            jobExecutor.execute(job.get());
            jobQueue.markCompleted(job.get().getId());

        } catch (RetryableException e) {
            // Exponential backoff: 2^attempt minutes
            Duration backoff = Duration.ofMinutes(
                (long) Math.pow(2, job.get().getAttempts()));
            jobQueue.scheduleRetry(job.get().getId(),
                Instant.now().plus(backoff),
                e.getMessage());

        } catch (FatalException e) {
            // Non-retryable: mark failed immediately
            jobQueue.markFailed(job.get().getId(), e.getMessage());
        }
    }
}

